#!/usr/bin/env python3

# Human P53 protein target sequence
target_protein = ""

# DNA sequences for the 4 plasmids
plasmid_sequences = {
    'A': "",
    
    'B': "",
    
    'C': "",
    
    'D': ""
}

def translate_dna_to_protein(dna_sequence):
    """Translate DNA sequence to protein using standard genetic code"""
    genetic_code = {
        'TTT': 'F', 'TTC': 'F', 'TTA': 'L', 'TTG': 'L',
        'TCT': 'S', 'TCC': 'S', 'TCA': 'S', 'TCG': 'S',
        'TAT': 'Y', 'TAC': 'Y', 'TAA': '*', 'TAG': '*',
        'TGT': 'C', 'TGC': 'C', 'TGA': '*', 'TGG': 'W',
        'CTT': 'L', 'CTC': 'L', 'CTA': 'L', 'CTG': 'L',
        'CCT': 'P', 'CCC': 'P', 'CCA': 'P', 'CCG': 'P',
        'CAT': 'H', 'CAC': 'H', 'CAA': 'Q', 'CAG': 'Q',
        'CGT': 'R', 'CGC': 'R', 'CGA': 'R', 'CGG': 'R',
        'ATT': 'I', 'ATC': 'I', 'ATA': 'I', 'ATG': 'M',
        'ACT': 'T', 'ACC': 'T', 'ACA': 'T', 'ACG': 'T',
        'AAT': 'N', 'AAC': 'N', 'AAA': 'K', 'AAG': 'K',
        'AGT': 'S', 'AGC': 'S', 'AGA': 'R', 'AGG': 'R',
        'GTT': 'V', 'GTC': 'V', 'GTA': 'V', 'GTG': 'V',
        'GCT': 'A', 'GCC': 'A', 'GCA': 'A', 'GCG': 'A',
        'GAT': 'D', 'GAC': 'D', 'GAA': 'E', 'GAG': 'E',
        'GGT': 'G', 'GGC': 'G', 'GGA': 'G', 'GGG': 'G'
    }
    
    protein = ""
    for i in range(0, len(dna_sequence), 3):
        codon = dna_sequence[i:i+3]
        if len(codon) == 3:
            protein += genetic_code.get(codon, 'X')
    
    return protein

def compare_sequences(seq1, seq2):
    """Compare two sequences and identify differences"""
    differences = []
    min_len = min(len(seq1), len(seq2))
    
    for i in range(min_len):
        if seq1[i] != seq2[i]:
            differences.append({
                'position': i + 1,
                'target': seq1[i],
                'actual': seq2[i]
            })
    
    if len(seq1) != len(seq2):
        differences.append({
            'position': 'length',
            'target': len(seq1),
            'actual': len(seq2)
        })
    
    return differences

def count_codons(dna_sequence):
    """Count codon usage in DNA sequence"""
    codon_counts = {}
    for i in range(0, len(dna_sequence), 3):
        codon = dna_sequence[i:i+3]
        if len(codon) == 3:
            codon_counts[codon] = codon_counts.get(codon, 0) + 1
    return codon_counts

# E. coli codon preferences (simplified - common vs rare codons)
ecoli_rare_codons = {
    'AGA': 'R', 'AGG': 'R', 'CGA': 'R',  # Rare arginine codons
    'CCC': 'P',  # Rare proline codon
    'GGA': 'G',  # Less preferred glycine
    'CTA': 'L', 'TTA': 'L'  # Rare leucine codons
}

print("=== Human P53 Plasmid Analysis ===\n")

print(f"Target protein length: {len(target_protein)} amino acids")
print(f"Target protein: {target_protein}\n")

results = {}

for plasmid_name, dna_seq in plasmid_sequences.items():
    print(f"=== Plasmid {plasmid_name} Analysis ===")
    
    # Translate DNA to protein
    translated_protein = translate_dna_to_protein(dna_seq)
    
    # Remove stop codon if present
    if translated_protein.endswith('*'):
        translated_protein = translated_protein[:-1]
    
    print(f"Translated protein length: {len(translated_protein)} amino acids")
    
    # Compare with target
    differences = compare_sequences(target_protein, translated_protein)
    
    if not differences:
        print("✅ CORRECT: 100% match with target protein")
        is_correct = True
    else:
        print(f"❌ INCORRECT: {len(differences)} difference(s) found:")
        for diff in differences:
            if diff['position'] == 'length':
                print(f"   Length mismatch: target {diff['target']}, actual {diff['actual']}")
            else:
                print(f"   Position {diff['position']}: {diff['target']} → {diff['actual']}")
        is_correct = False
    
    # Count rare codons
    codon_counts = count_codons(dna_seq)
    rare_codon_count = 0
    rare_codons_found = []
    
    for codon, count in codon_counts.items():
        if codon in ecoli_rare_codons:
            rare_codon_count += count
            rare_codons_found.append(f"{codon}({ecoli_rare_codons[codon]}): {count}")
    
    print(f"Rare E. coli codons: {rare_codon_count} total")
    if rare_codons_found:
        print(f"   {', '.join(rare_codons_found)}")
    
    results[plasmid_name] = {
        'correct_sequence': is_correct,
        'rare_codon_count': rare_codon_count,
        'differences': differences,
        'translated_protein': translated_protein
    }
    
    print()

print("=== Summary ===")
print("Sequence accuracy:")
for plasmid, result in results.items():
    status = "✅ CORRECT" if result['correct_sequence'] else "❌ INCORRECT"
    print(f"  Plasmid {plasmid}: {status}")

print("\nE. coli optimization (rare codon count):")
correct_plasmids = [(p, r) for p, r in results.items() if r['correct_sequence']]
correct_plasmids.sort(key=lambda x: x[1]['rare_codon_count'])

for plasmid, result in correct_plasmids:
    print(f"  Plasmid {plasmid}: {result['rare_codon_count']} rare codons")

if correct_plasmids:
    best_plasmid = correct_plasmids[0][0]
    print(f"\n🏆 RECOMMENDATION: Use Plasmid {best_plasmid}")
    print(f"   - Produces correct Human P53 protein")
    print(f"   - Has fewest rare E. coli codons ({correct_plasmids[0][1]['rare_codon_count']})")
    print(f"   - Optimal for fast expression in E. coli BL21")
else:
    print("\n❌ No plasmids produce the correct protein sequence!")